#include <vector>
#include <unordered_set>

class Solution {
public:
    bool isThreeFibonacciSum(int n) {
        std::vector<int> fibs = {1, 2};
        while (fibs.back() < n) {
            fibs.push_back(fibs.back() + fibs[fibs.size() - 2]);
        }
        std::unordered_set<int> fib_set(fibs.begin(), fibs.end());

        int m = fibs.size();
        for (int i = 0; i < m; ++i) {
            for (int j = i; j < m; ++j) {
                int rem = n - fibs[i] - fibs[j];
                if (rem >= fibs[j] && fib_set.count(rem)) {
                    return true;
                }
            }
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean isThreeFibonacciSum(int n) {
        List<Integer> fibs = new ArrayList<>();
        fibs.add(1);
        fibs.add(2);
        while (fibs.get(fibs.size() - 1) < n) {
            int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
            fibs.add(next);
        }
        Set<Integer> fibSet = new HashSet<>(fibs);

        int m = fibs.size();
        for (int i = 0; i < m; i++) {
            for (int j = i; j < m; j++) {
                int rem = n - fibs.get(i) - fibs.get(j);
                if (rem >= fibs.get(j) && fibSet.contains(rem)) {
                    return true;
                }
            }
        }
        return false;
    }
}

